  font-weight: 500;
  border: none;
  outline: none;
  background: var(--primary, #1976d2);
  color: #fff;
  border-radius: 7px;
  padding: 9px 24px;
  margin: 2px 0;
  cursor: pointer;
  font-size: 16px;
  transition: background 0.16s;
}
.btn:hover, .btn-large:hover {
  background: var(--accent, #ff9800);
  color: #fff;
}

.modal {
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 8px 28px rgba(25,118,210,0.14);
  padding: 32px;
}
.sidebar {
  min-width: 200px;
  background: var(--secondary);
  border-right: 1px solid #ececec;
  color: #fff;
}

input, select, textarea {
  font-size: 16px;
  padding: 10px 14px;
  border: 1.3px solid var(--primary, #1976d2);
  border-radius: 6px;
  margin: 6px 0 0 0;
  outline: none;
  transition: border-color 0.17s;
  background: #f5f8fe;
}
input:focus, select:focus, textarea:focus {
  border: 1.7px solid var(--accent, #ff9800);
  background: #fff;
}

table {
  border-collapse: collapse;
  width: 100%;
  font-size: 15px;
}
th, td {
  padding: 12px 16px;
}
th {
  color: #1976d2;
  background: #f2f4f8;
  font-weight: 700;
}
td {
  background: #fff;
  color: #191919;
}
tr {
  border-bottom: 1px solid #e9e9ef;
}

